contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address caller,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) public payable {
        require(true);

        bytes4 returned;
        bool succeeded;
        try c.onERC721Received(caller, from, tokenId, data) returns (bytes4 v) {
            returned = v;
            succeeded = true;
        } catch {
            succeeded = false;
        }

        assert(!succeeded || returned == bytes4(0x150b7a02));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, bytes calldata data) public payable {
        require(tokenId <= type(uint256).max);

        bytes4 returned = c.onERC721Received(address(this), address(this), tokenId, data);

        assert(returned == bytes4(0x150b7a02));
    }

    receive() external payable {}
}

